package edu.ankara.audiometer.infrastructure;
import edu.ankara.audiometer.domain.config.AudiometryConfig;import edu.ankara.audiometer.domain.model.*;import edu.ankara.audiometer.infrastructure.export.CsvAudiogramExporter;import edu.ankara.audiometer.infrastructure.serial.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class SerialProtocolTest { @Test void parsesResponseVariantsAndIgnoresInvalid(){ assertTrue(SerialProtocol.parseResponseMessage(" RESPONSE\r\n").orElseThrow() instanceof ProtocolEvent.Response); assertTrue(SerialProtocol.parseResponseMessage("response").orElseThrow() instanceof ProtocolEvent.Response); assertTrue(SerialProtocol.parseResponseMessage("nonsense").isEmpty()); } @Test void createsValidatedToneCommand(){ var p=new TonePresentation(Ear.RIGHT,new FrequencyHz(1000),new IntensityDbHL(40),1,Optional.empty(),PresentationDirection.INITIAL,false); var cmd=SerialCommand.tone(p,AudiometryConfig.defaults()); assertTrue(cmd.isOk()); assertEquals("TONE;EAR=RIGHT;FREQ=1000;DB=40;DURATION_MS=1000",cmd.orElse(null).value()); } @Test void csvExportRowsMatchPoints(){ var point=new AudiogramPoint(Ear.RIGHT,new FrequencyHz(1000),new IntensityDbHL(20),ThresholdCriterion.TWO_OUT_OF_THREE_ASCENDING,3,3,"ok"); var s=TestState.initial(AudiometryConfig.defaults()).withAudiogram(Audiogram.empty().add(point,false)); String csv=new CsvAudiogramExporter().export(s); assertEquals(2,csv.lines().count()); assertTrue(csv.contains("RIGHT,1000,20")); } }
